use vstd::prelude::*;

/// Returns, for each inner vector in `lst`, its first element.
/// 
/// Requires that no inner vector is empty.
#[requires(forall(|i: usize| i < lst.len() ==> lst[i].len() > 0))]
#[ensures(result.len() == lst.len())]
#[ensures(forall(|i: usize| i < lst.len() ==> result[i] == lst[i][0]))]
fn get_first_elements(lst: Vec<Vec<i32>>) -> Vec<i32> {
    lst.into_iter()
        .map(|inner| inner[0])
        .collect()
}

